package com.nequard.alerts;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="alerts") public class Alert{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;@Column(nullable=false)String title;@Column(nullable=false)String severity;@Column(nullable=false)String status="OPEN";UUID deviceId;UUID organizationId;String message;Instant createdAt=Instant.now();public UUID getId(){return id;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getSeverity(){return severity;}public void setSeverity(String v){severity=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public UUID getDeviceId(){return deviceId;}public void setDeviceId(UUID v){deviceId=v;}public UUID getOrganizationId(){return organizationId;}public void setOrganizationId(UUID v){organizationId=v;}public String getMessage(){return message;}public void setMessage(String v){message=v;}public Instant getCreatedAt(){return createdAt;}}